  query GetProducts {
    products { id name price inStock }
  }
`;

function ProductList() {
  const { loading, error, data } = useQuery(GET_PRODUCTS);
  if (loading) return 'Loading...';
  if (error) return ;
  return data.products.map(p => ).join('\n');
}
