Aggregation Basics

Kategori: MongoDB  Minggu 4: Aggregation Basics

Learning Objectives

$match for filtering
$group for aggregation
$project for shaping output
$unwind for expanding arrays
$sort and $limit

--Program: Aggregation Pipeline

javascript
async function main() {
    const client = new MongoClient('mongodb://localhost:27017');
    await client.connect();
    const produk = client.db('toko_db').collection('produk');

    // $match: filter
    const elektronik = await produk.aggregate([
        { $match: { kategori: 'Elektronik' } }
    ]).toArray();
    console.log('Elektronik:', elektronik.length);

    // $group: kelompokkan dan agregasi
    const perKategori = await produk.aggregate([
        { $group: {
            _id: '$kategori',
            totalProduk: { $sum: 1 },
            rataHarga: { $avg: '$harga' },
            maxHarga: { $max: '$harga' },
            totalStok: { $sum: '$stok' }
        }},
        { $sort: { totalProduk: -1 } }
    ]).toArray();
    console.log('Per kategori:', perKategori);

    // $project: bentuk output
    const ringkas = await produk.aggregate([
        { $project: {
            nama: 1,
            harga: 1,
            kategori: 1,
            nilaiStok: { $multiply: ['$harga', '$stok'] },
            _id: 0
        }},
        { $sort: { nilaiStok: -1 } },
        { $limit: 5 }
    ]).toArray();
    console.log('Top 5 nilai stok:', ringkas);

    // $unwind: expand array
    const tags = await produk.aggregate([
        { $unwind: '$tags' },
        { $group: { _id: '$tags', count: { $sum: 1 } } },
        { $sort: { count: -1 } }
    ]).toArray();
    console.log('Tags:', tags);

    // $count
n    const total = await produk.aggregate([
        { $match: { harga: { $gt: 500000 } } },
        { $count: 'produk_mahal' }
    ]).toArray();
    console.log('Produk mahal:', total);

    await client.close();
}
main().catch(console.error);
--Key Concepts

Aggregation Pipeline
Data transformation stages: $match -> $g

Schema Design Patterns

Kategori: MongoDB  Minggu 5: Schema Design Patterns

Learning Objectives

Embedding vs Referencing
Embedding pattern 1-to-Few
Referencing pattern 1-to-Many
$lookup for joins
Bucket and outlier patterns

--Program: Schema Design Patterns

javascript
// Pola Schema Design MongoDB

// Embedding (1-to-Few)
const pelangganEmbedded = {
    _id: ObjectId('...'),
    nama: 'Budi Santoso',
    email: 'budi@email.com',
    alamat: [
        { jalan: 'Jl. Sudirman', kota: 'Jakarta', utama: true },
        { jalan: 'Jl. Thamrin', kota: 'Jakarta', utama: false }
    ]
};

// Referencing (1-to-Many)
const pesananRef = {
    _id: ObjectId('...'),
    pelanggan_id: ObjectId('...'),  // Reference ke pelanggan
    tanggal: new Date(),
    items: [
        { produk_id: ObjectId('...'), nama: 'Laptop', qty: 1, harga: 12500000 },
        { produk_id: ObjectId('...'), nama: 'Mouse', qty: 2, harga: 350000 }
    ],
    total: 13200000
};

// Lookup (join)
async function getPesananWithPelanggan() {
    const pesanan = client.db('toko_db').collection('pesanan');
    return await pesanan.aggregate([
        { $lookup: {
            from: 'pelanggan',
            localField: 'pelanggan_id',
            foreignField: '_id',
            as: 'pelanggan'
        }},
        { $unwind: '$pelanggan' },
        { $project: {
            'pelanggan.nama': 1,
            'pelanggan.email': 1,
            total: 1,
            tanggal: 1
        }}
    ]).toArray();
}

// Pola Bucket (time-series)
const sensorReading = {
    sensor_id: 'temp-01',
    timestamp: new Date(),
    value: 25.5
};

// Pola Outlier (pola subscription)
const userWithOutlier = {
    _id: ObjectId('...'),
    nama: 'Budi',
    subscription: 'premium'  // Outlier field
};
--Key Concepts

Embedding
Store related data in one document. Good for 1-to-Few.

Referencing
Store reference (_id) to another document. Good for 1-to-Many.

$lookup
Left outer join between collections.

Bucket Pattern
