// produk.service.ts
import { Injectable } from '@nestjs/common';
@Injectable()
export class ProdukService {
  private daftar = [{ id: 1, nama: "Beras", harga: 62000 }];
  semua(){ return this.daftar; }
  tambah(p){ this.daftar.push({ id: Date.now(), ...p }); return p; }
}

