    @Test
    void shouldReturnProductById() {
        // Arrange
        Product product = new Product("Laptop", 15000000.0);
        product.setId(1L);
        when(productRepository.findById(1L)).thenReturn(Optional.of(product));

        // Act
        Optional<Product> result = productService.getProductById(1L);

