// Template Literal Types
type EventName = "click"  "blur";
type ElementId = "button"  "form";

// Combine template literals
type EventString = ;
// "button:click"  "form:blur"

// Capitalize, Uncapitalize, Uppercase, Lowercase
type Greeting = "hello world";
type Capitalized = Capitalize<Greeting>;  // "Hello world"
type Uppercased = Uppercase<Greeting>;   // "HELLO WORLD"
type Lowercased = Lowercase<Greeting>;   // "hello world"

// Conditional Types
type IsString<T> = T extends string ? true : false;
type Test1 = IsString<"hello">;  // true
type Test2 = IsString<42>;       // false

// infer keyword
type ArrayElement<T> = T extends (infer E)[] ? E : never;
type NumElem = ArrayElement<number[]>;     // number
type StrElem = ArrayElement<string[]>;     // string

// Distributive Conditional Types
type ToArray<T> = T extends any ? T[] : never;
type StringOrNumArray = ToArray<string  number[]

// Mapped Types
type Readonly<T> = {
    readonly [K in keyof T]: T[K];
};

type Partial<T> = {
    [K in keyof T]?: T[K];
};

// Key remapping
type Getters<T> = {
    [K in keyof T as ]: () => T[K];
};

interface User {
    name: string;
    age: number;
    email: string;
}

type UserGetters = Getters<User>;
// { getName: () => string; getAge: () => number; getEmail: () => string }

// Recursive types
type DeepReadonly<T> = {
    readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K];
};

interface Config {
    server: { host: string; port: number };
    database: { url: string; pool: number };
}

type ReadonlyConfig = DeepReadonly<Config>;

// Branded Types (Nominal Typing)
type Brand<T, B> = T & { __brand: B }

