// Testing dengan type safety
// Framework: Vitest / Jest dengan TypeScript

// Test utilities dengan types
interface TestContext {
    name: string;
    fn: () => void | Promise<void>;
}

class TypeSafeRunner {
    private tests: TestContext[] = [];
    private passed = 0;
    private failed = 0;

    test(name: string, fn: () => void | Promise<void>): void {
        this.tests.push({ name, fn });
    }

    async run(): Promise<void> {
        console.log("=== Type-Safe Test Runner ===");
        for (const { name, fn } of this.tests) {
            try {
                await fn();
                this.passed++;
                console.log("  ✓", name);
            } catch (err: unknown) {
                this.failed++;
                const msg = err instanceof Error ? err.message : String(err);
                console.log("  ✗", name);
                console.log("   ", msg);
            }
        }
        console.log();
    }
}

// Type-safe assertions
function expect<T>(actual: T) {
    return {
        toBe(expected: T): void {
            if (actual !== expected) {
                throw new Error();
            }
        },
        toEqual(expected: T): void {
            if (JSON.stringify(actual) !== JSON.stringify(expected)) {
                throw new Error();
            }
        },
        toBeGreaterThan(expected: number): void {
            if (typeof actual !== "number" || actual <= expected) {
                throw new Error();
            }
        },
        toBeType<T2>(): void {
            // Runtime type check placeholder
            console.log("  (type check passed)");
        }
    };
}

// Test subjects
function add(a: number, b: number): num

